// Agrupa el CSV del conteo (Comunidad, Fecha, Teléfono) por comunidad y lo deja en el formato que pide la carga del CRM: [{t: '549...', f: 'AAAA-MM-DD'}].
const archivo = $('Descargar CSV').first().json.name || $('Solo conteos').first().json.name || 'conteo-miembros.csv';
const porComunidad = {};
let leidas = 0, invalidas = 0;
for (const it of $input.all()) {
  const r = Object.fromEntries(Object.entries(it.json).map(([k, v]) => [k.replace(/^\uFEFF/, '').trim(), v])); // el CSV trae una marca invisible (BOM) pegada al primer encabezado: se la saca
  const comunidad = String(r['Comunidad'] ?? '').trim();
  const tel = String(r['Teléfono'] ?? r['Telefono'] ?? '').replace(/\D/g, '');
  const m = String(r['Fecha'] ?? '').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  leidas++;
  if (!comunidad || tel.length < 8 || tel.length > 15) { invalidas++; continue; }
  const f = m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : null;
  (porComunidad[comunidad] ||= []).push({ t: tel, f });
}
return Object.entries(porComunidad).map(([comunidad, filas]) => ({ json: { archivo, comunidad, filas, filas_leidas: leidas, invalidos: invalidas } }));

// Une cada comunidad del archivo con su id en el CRM (por el nombre exacto; el grupo "Cortado en Jarrito" del archivo se une con "Cortado en Jarrito (general)"). Si un nombre no existe, la carga de esa comunidad NO se hace.
const ids = {};
for (const c of $('Supabase: comunidades').all().flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))) ids[c.nombre] = c.id;
return $('Armar cargas').all().map((i) => ({ json: { ...i.json, comunidad_id: ids[i.json.comunidad] || ids[i.json.comunidad + ' (general)'] || null } }));

// FRENO DE SEGURIDAD: decide, comunidad por comunidad, si la carga se hace sola o espera a una persona.
// Una lectura incompleta de WhatsApp (por ejemplo, un grupo que no terminó de cargar) haría parecer que mucha gente se fue.
const MODO = 'prueba';             // 'prueba' = solo mira la vista previa y avisa, NO carga. Cambiar a 'real' cuando ya probaste.
const MAX_SALIDAS_PCT = 10;        // si la carga dejaría más de este % de los miembros actuales como salidas, no se hace sola
const MIN_TAMANO_PCT = 80;         // el archivo tiene que traer al menos este % de los miembros actuales

// Una fila por comunidad: la vista previa llega en el mismo orden que las cargas de "Unir con el id".
const cargas = $('Unir con el id').all();
return $input.all().map((it, idx) => {
  const carga = cargas[idx].json;
  const vp = Array.isArray(it.json) ? it.json[0] : it.json;
  const actuales = Number(vp.activos_actuales) || 0;
  const salidas = Number(vp.salidas) || 0;
  const total = Number(vp.total_archivo) || 0;
  const motivos = [];
  if (!carga.comunidad_id) motivos.push('la comunidad no existe en el CRM con ese nombre');
  if (actuales > 0 && salidas / actuales * 100 > MAX_SALIDAS_PCT) motivos.push(`dejaría ${salidas} salidas de ${actuales} miembros (más del ${MAX_SALIDAS_PCT} %)`);
  if (actuales > 0 && total / actuales * 100 < MIN_TAMANO_PCT) motivos.push(`el archivo trae ${total} números y el grupo tenía ${actuales}: parece incompleto`);
  const ok = motivos.length === 0;
  return { json: { ...carga, vista_previa: vp, hacer_carga: ok && MODO === 'real', modo: MODO, ok, motivos, resumen: `${carga.comunidad}: ${total} en el archivo, ${vp.nuevos ?? '?'} nuevos, ${salidas} salidas, ${vp.duplicados ?? '?'} ya estaban` } };
});

// Texto del aviso: qué se cargó solo y qué quedó esperando a una persona.
const filas = $input.all().map((i) => i.json);
const cargadas = filas.filter((r) => r.hacer_carga);
const esperan = filas.filter((r) => !r.hacer_carga);
const li = (r) => `<li>${r.resumen}${r.motivos && r.motivos.length ? ' — <b>no se cargó:</b> ' + r.motivos.join('; ') : (r.modo === 'prueba' ? ' — <i>modo prueba: no se cargó</i>' : '')}</li>`;
const html = `<p>Carga automática de miembros (${filas[0]?.archivo ?? ''}).</p>
${cargadas.length ? '<p><b>Cargadas:</b></p><ul>' + cargadas.map(li).join('') + '</ul>' : ''}
${esperan.length ? '<p><b>Esperan a una persona (o modo prueba):</b></p><ul>' + esperan.map(li).join('') + '</ul><p>Para cargarlas a mano: Overview → Cargar miembros → lista completa.</p>' : ''}`;
return [{ json: { asunto: cargadas.length === filas.length ? 'Miembros cargados en el CRM' : 'Carga de miembros: hay comunidades para revisar', html } }];
